INSERT INTO `bahar-db`.`t_duty_source` (duty_id, source_id) SELECT 1, source_id FROM `bahar-db`.`t_source` WHERE source_id BETWEEN 999 AND 1999;
INSERT INTO `bahar-db`.`t_account_duty` (acct_id, duty_id) SELECT a.acct_id, 1 FROM `bahar-db`.`t_account` a WHERE NOT EXISTS (SELECT 1 FROM `bahar-db`.`t_account_duty` d WHERE d.acct_id = a.acct_id AND d.duty_id = 1);
